<script setup>
import { ref, computed, onMounted, onUnmounted } from "vue";

const props = defineProps({
  // 0..1 — seberapa jauh garisnya sudah terisi.
  progres: { type: Number, default: 0 },
});

// Pecahan letak tiap ikon, urut menaik. Dipakai pemanggil sebagai patokan
// supaya butir di kolom kiri menyala tepat saat garisnya sampai ke ikonnya.
const emit = defineEmits(["terukur"]);

const jalur = ref(null);
const panjang = ref(0);
const pecahanIkon = ref([]);

// Titik pusat tiap lingkaran ikon, disalin dari berkas SVG-nya.
const PUSAT = [
  [229.683, 50.0],
  [375.653, 303.0],
  [639.796, 50.0],
  [105.653, 256.0],
  [70.0, 560.0],
  [549.653, 560.0],
];

const ukurPecahan = () => {
  const el = jalur.value;
  if (!el) return;
  const total = el.getTotalLength();
  panjang.value = total;

  const LANGKAH = 400;
  const dekat = PUSAT.map(() => ({ jarak: Infinity, pecahan: 0 }));
  for (let i = 0; i <= LANGKAH; i++) {
    const p = el.getPointAtLength((total * i) / LANGKAH);
    PUSAT.forEach(([x, y], k) => {
      const j = (p.x - x) ** 2 + (p.y - y) ** 2;
      if (j < dekat[k].jarak) {
        dekat[k].jarak = j;
        dekat[k].pecahan = i / LANGKAH;
      }
    });
  }
  // Jalurnya digambar mundur dari ujung, jadi pecahan tiap ikon dibalik:
  // ikon di ujung jalur (kanan-atas) jadi yang pertama disentuh garis.
  pecahanIkon.value = dekat.map((d) => 1 - d.pecahan);
  emit(
    "terukur",
    [...pecahanIkon.value].sort((a, b) => a - b),
  );
};

onMounted(ukurPecahan);

// Ikon muncul sekali saat grafiknya masuk layar — tidak menunggu garisnya.
const tampil = ref(false);
let pengintai = null;

onMounted(() => {
  const el = jalur.value?.ownerSVGElement;
  if (!el || typeof IntersectionObserver === "undefined") {
    tampil.value = true;
    return;
  }
  pengintai = new IntersectionObserver(
    (isi) => {
      if (!isi.some((e) => e.isIntersecting)) return;
      tampil.value = true;
      pengintai?.disconnect();
      pengintai = null;
    },
    { threshold: 0.2 },
  );
  pengintai.observe(el);
});

onUnmounted(() => pengintai?.disconnect());

// Berwarna hanya setelah garisnya sampai ke ikon itu; sebelum itu abu-abu.
// Ini terpisah dari `tampil` yang cuma mengurus animasi munculnya.
const menyala = computed(() =>
  PUSAT.map((_, i) => {
    const p = pecahanIkon.value[i];
    if (p === undefined) return false;
    return props.progres >= p;
  }),
);

// Urutan timbulnya mengikuti arah garis: kanan-atas dulu, kiri-bawah terakhir.
const JEDA_MS = 110;

const urutan = computed(() => {
  const p = pecahanIkon.value;
  if (p.length !== PUSAT.length) return PUSAT.map((_, i) => i);
  const naik = p
    .map((nilai, i) => ({ nilai, i }))
    .sort((a, b) => a.nilai - b.nilai);
  const peringkat = [];
  naik.forEach((x, k) => (peringkat[x.i] = k));
  return peringkat;
});

const gayaIkon = (i) => {
  const d = urutan.value[i] * JEDA_MS;
  return { transitionDelay: `${d}ms, ${d}ms, 0ms` };
};

const gayaIsi = computed(() => {
  const L = panjang.value;
  if (!L) return { strokeDasharray: "0 1", strokeDashoffset: 0 };
  const q = Math.min(1, Math.max(0, props.progres));
  // Offset NEGATIF menggeser pola garis ke depan, sehingga bagian yang
  // terlihat tumbuh dari ujung jalur ke pangkalnya: atas dulu, bawah terakhir.
  return { strokeDasharray: `${L}`, strokeDashoffset: -L * (1 - q) };
});
</script>

