<style scoped>
/* Ikon belum muncul sampai garisnya sampai ke sana, lalu timbul satu per satu.
   transform-box: fill-box membuat skalanya berporos di ikonnya sendiri, bukan
   di titik nol kanvas SVG. */
.ikon {
  opacity: 0;
  transform: scale(0.55);
  transform-box: fill-box;
  transform-origin: center;
  /* Ditulis terurai supaya jeda bertahapnya (dari gayaIkon) bisa dikenakan
     ke opacity dan transform saja, tidak ke perubahan warnanya. */
  transition-property: opacity, transform, filter;
  transition-duration: 400ms, 450ms, 450ms;
  transition-timing-function: ease, cubic-bezier(0.22, 1, 0.36, 1), ease;
}

.ikon.tampil {
  opacity: 1;
  transform: scale(1);
}

/* Diredupkan lewat filter, bukan properti opacity, supaya tidak berebut
   dengan opacity yang dipakai animasi munculnya. */
.ikon.redup {
  filter: grayscale(1) opacity(0.5);
}

@media (prefers-reduced-motion: reduce) {
  .ikon {
    transition: none;
    transform: none;
  }
}
</style>
